        enum_lines.append("} ApirBackendCommandType;")

        # Generate function name mapping
        func_lines = []
        func_lines.append("static inline const char * apir_dispatch_command_name(ApirBackendCommandType type) {")
        func_lines.append("    switch (type) {")

